import ghidra.app.decompiler.*; import ghidra.app.script.GhidraScript; import ghidra.program.model.address.*; import ghidra.program.model.listing.*;
public class SweepScalarEvidence extends GhidraScript { public void run()throws Exception{DecompInterface d=new DecompInterface();d.openProgram(currentProgram);long[] xs={0x004d6560L,0x005ddb9cL};for(long x:xs){Function f=getFunctionAt(toAddr(x));println("=== "+toAddr(x)+" "+f+" ===");if(f!=null){DecompileResults r=d.decompileFunction(f,600,monitor);if(r.getDecompiledFunction()!=null)println(r.getDecompiledFunction().getC());}Address a=toAddr(x);println("DATA="+getDataAt(a));}d.dispose();}}
